<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/layout.php';$me=has_permission('pos.manage')?require_permission('pos.manage'):require_permission('shop.manage');mp550_bootstrap_legacy_shops();$flash='';$error='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$action=(string)($_POST['action']??'assign');if($action==='assign'){$shop=(int)$_POST['shop_id'];$uid=(int)$_POST['user_id'];if(!$shop||!$uid)throw new RuntimeException('Choose shop and user.');$perms=['sales'=>!empty($_POST['can_sales'])?1:0,'discounts'=>!empty($_POST['can_discounts'])?1:0,'returns'=>!empty($_POST['can_returns'])?1:0,'cash_drawer'=>!empty($_POST['can_cash_drawer'])?1:0];db()->prepare("INSERT INTO marketplace_pos_assignments_v550(shop_id,user_id,assigned_by,terminal_name,permissions_json,status,created_at,updated_at) VALUES(?,?,?,?,?,1,NOW(),NOW()) ON DUPLICATE KEY UPDATE assigned_by=VALUES(assigned_by),terminal_name=VALUES(terminal_name),permissions_json=VALUES(permissions_json),status=1,updated_at=NOW()")->execute([$shop,$uid,(int)$me['id'],trim((string)($_POST['terminal_name']??'Main Counter'))?:'Main Counter',mp550_json($perms)]);$flash='POS access assigned. User can open /seller-pos.php.';}elseif($action==='toggle'){$id=(int)$_POST['assignment_id'];db()->prepare('UPDATE marketplace_pos_assignments_v550 SET status=IF(status=1,0,1),updated_at=NOW() WHERE id=?')->execute([$id]);$flash='POS assignment status changed.';}elseif($action==='close_shift'){$id=(int)$_POST['shift_id'];db()->prepare("UPDATE marketplace_pos_shifts_v550 SET status='closed',closed_at=COALESCE(closed_at,NOW()),closing_cash=COALESCE(closing_cash,opening_cash+sales_total) WHERE id=?")->execute([$id]);$flash='POS shift closed.';}}}catch(Throwable $e){$error=$e->getMessage();}$shops=mp550_shops([],500);$assignments=mp550_pos_assignments();$users=[];$shifts=[];try{$users=db()->query('SELECT id,name,email,phone FROM users ORDER BY name LIMIT 1500')->fetchAll()?:[];}catch(Throwable $e){}try{$shifts=db()->query('SELECT sh.*,s.name shop_name,u.name user_name,pa.terminal_name FROM marketplace_pos_shifts_v550 sh JOIN marketplace_shops_v550 s ON s.id=sh.shop_id JOIN users u ON u.id=sh.user_id LEFT JOIN marketplace_pos_assignments_v550 pa ON pa.id=sh.assignment_id ORDER BY sh.id DESC LIMIT 100')->fetchAll()?:[];}catch(Throwable $e){}$open=count(array_filter($shifts,fn($s)=>$s['status']==='open'));$sales=array_sum(array_map(fn($s)=>(float)$s['sales_total'],$shifts));page_start('Seller POS Assignment Center',true);?><link rel="stylesheet" href="/assets/marketplace-admin-5.5.0.css?v=550"><div class="mp550-admin"><section class="mp550-admin-hero pos-hero"><div><span><i></i> v5.5.0 · SELLER POS</span><h2>POS Assignment <em>Center</em></h2><p>Assign any shopkeeper or user to a specific shop and terminal. Their POS view only shows products and sales for shops they are allowed to access.</p></div><div><a class="btn ghost" target="_blank" href="/seller-pos.php">Open POS ↗</a><a class="btn" href="/admin/shop.php?tab=pos">Marketplace POS Dashboard</a></div></section><?php if($flash):?><div class="mp550-admin-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="mp550-admin-alert err"><?=e($error)?></div><?php endif;?><section class="mp550-admin-kpis"><div><span>Assignments</span><b><?=count($assignments)?></b><small>Shop/user pairs</small></div><div><span>Open shifts</span><b><?=$open?></b><small>Currently active</small></div><div><span>Recorded POS sales</span><b><?=mp550_money($sales)?></b><small>Recent shift total</small></div><div><span>Assignable shops</span><b><?=count($shops)?></b><small>Active storefronts</small></div></section><section class="admin-split"><div class="panel"><div class="panel-head"><div><span>ACCESS MATRIX</span><h3>POS assignments</h3></div></div><div class="table-wrap"><table><thead><tr><th>Terminal</th><th>Shop</th><th>User</th><th>Permissions</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($assignments as $a):$per=json_decode((string)($a['permissions_json']??'{}'),true)?:[];?><tr><td><b><?=e($a['terminal_name'])?></b></td><td><?=e($a['shop_name'])?></td><td><?=e($a['user_name'])?><small><?=e($a['user_email'])?></small></td><td><?=e(implode(' · ',array_keys(array_filter($per))))?></td><td><em class="status <?=$a['status']?'active':'paused'?>"><?=$a['status']?'active':'disabled'?></em></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="assignment_id" value="<?=(int)$a['id']?>"><button><?=$a['status']?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></tbody></table></div><div class="panel-head sub"><div><span>SHIFT ACTIVITY</span><h3>Recent POS shifts</h3></div></div><div class="table-wrap"><table><thead><tr><th>Shop / Terminal</th><th>Cashier</th><th>Opened</th><th>Sales</th><th>Orders</th><th>Status</th></tr></thead><tbody><?php foreach($shifts as $s):?><tr><td><b><?=e($s['shop_name'])?></b><small><?=e($s['terminal_name']??'POS')?></small></td><td><?=e($s['user_name'])?></td><td><?=e(date('d M · h:i A',strtotime($s['opened_at'])))?></td><td><b><?=mp550_money((float)$s['sales_total'])?></b></td><td><?=(int)$s['order_count']?></td><td><?php if($s['status']==='open'):?><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="close_shift"><input type="hidden" name="shift_id" value="<?=(int)$s['id']?>"><em class="status active">open</em><button>Force close</button></form><?php else:?><em class="status completed">closed</em><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><aside class="panel form-panel"><h3>Assign POS access</h3><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assign"><label>Shop<select name="shop_id" required><option value="">Select shop</option><?php foreach($shops as $s):?><option value="<?=(int)$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>User / shopkeeper<select name="user_id" required><option value="">Select user</option><?php foreach($users as $u):?><option value="<?=(int)$u['id']?>"><?=e($u['name'].' · '.$u['email'])?></option><?php endforeach;?></select></label><label>Terminal name<input name="terminal_name" value="Main Counter" required></label><div class="checks vertical"><label><input type="checkbox" name="can_sales" value="1" checked> Process sales</label><label><input type="checkbox" name="can_discounts" value="1" checked> Apply automatic discounts</label><label><input type="checkbox" name="can_returns" value="1"> Returns / refunds</label><label><input type="checkbox" name="can_cash_drawer" value="1" checked> Cash drawer / shift</label></div><button class="btn wide">Assign POS terminal</button><p class="form-note">After assignment the user signs in normally and opens <b>/seller-pos.php</b>. They only see assigned shops.</p></form></aside></section></div><?php page_end(); ?>
